function Stat({title,value,sub,icon,color}:{title:string;value:string|number;sub:string;icon:React.ReactNode;color:string}){return <GlassCard className="stat"><div className="stat-top"><span>{title}</span><div className={'stat-icon '+color}>{icon}</div></div><strong>{value}</strong><small>{sub}</small></GlassCard>}
function ResultTable({rows,teacher,onOpen}:{rows:Result[];teacher:boolean;onOpen:(id:number)=>void}){return rows.length?<div className="table-scroll"><table><thead><tr><th>ТЕСТ АТАУЫ</th>{teacher&&<th>СТУДЕНТ</th>}<th>КҮНІ</th><th>НӘТИЖЕ</th><th>МӘРТЕБЕСІ</th><th><span className="sr-only">Ашу</span></th></tr></thead><tbody>{rows.map(r=><tr key={r.id}><td><strong>{r.title}</strong><small>{r.subject}{r.demo?' · Демо':''}</small></td>{teacher&&<td>{r.student}</td>}<td className="muted nowrap">{date(r.started)}</td><td><div className="score-cell"><strong>{Math.round(r.score)}%</strong><span className="mini-track"><i style={{width:r.score+'%'}}/></span></div></td><td><span className={r.passed?'badge pass':'badge fail'}><span/>{r.passed?'Тапсырылды':'Қайта дайындалу'}</span></td><td><button className="icon-button" onClick={()=>onOpen(r.id)} aria-label={r.title+' нәтижесін ашу'}><ArrowUpRight size={18}/></button></td></tr>)}</tbody></table></div>:<Empty text="Нәтиже табылмады. Алғашқы тестті тапсырыңыз."/>}
function exportCSV(rows:Result[]){const cell=(s:unknown)=>'"'+String(s??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';const csv='\uFEFF'+[['Студент','Тест','Күні','Нәтиже %','Ұпай','Мәртебесі','Демо'],...rows.map(r=>[r.student,r.title,date(r.started),r.score,`${r.earned}/${r.total}`,r.passed?'Тапсырылды':'Тапсырылмады',r.demo?'Иә':'Жоқ'])].map(r=>r.map(cell).join(';')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download='SKAS_results.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function Login({onLogin}:{onLogin:(u:User)=>void}){
 const[role,setRole]=useState<'student'|'teacher'|'none'>('none'),[name,setName]=useState(''),[group,setGroup]=useState(''),[code,setCode]=useState(''),[error,setError]=useState(''),[busy,setBusy]=useState(false);
 async function send(e:React.FormEvent){e.preventDefault();setBusy(true);setError('');try{const data=await api<{token:string;user:User}>('/auth/login','POST',{role,name,group:role==='student'?'БҚ-332':group,code});token.set(data.token);onLogin(data.user)}catch(e){setError(e instanceof Error?e.message:'Қате')}finally{setBusy(false)}}
 return <div className="login-page"><div className="login-art"><div className="brand"><span className="brand-icon"><GraduationCap/></span><span>SKAS<span className="brand-small">SPATIAL · 5.0</span></span></div><div className="login-art-body"><span className="college-glow">NARXOZ COLLEGE</span><h1>SKAS 5.0<br/><span>Білімге жаңа көзқарас.</span></h1><p>Білімді бағалау жүйесі · Студенттер мен оқытушыларға арналған платформа</p><div className="login-orb"><GraduationCap size={100} strokeWidth={1}/></div><div className="login-features"><span><BookOpen/>140 сабақ</span><span><ShieldCheck/>7 пән</span><span><Send/>Бір кеңістік</span></div></div><small>Narxoz College · 2026</small></div><div className="login-form-wrap"><form className="login-form fade-in" onSubmit={send}><span className="college-glow">NARXOZ COLLEGE</span><h2>{role==='none'?'Кім болып кіресіз?':role==='student'?'Студент ретінде кіру':'Оқытушы ретінде кіру'}</h2><p>{role==='none'?'Жалғастыру үшін рөліңізді таңдаңыз.':role==='student'?'Тізімнен атыңызды таңдап, жеке кодыңызды енгізіңіз.':'Жеке растау кодын енгізіңіз.'}</p><div className="role-choices"><button type="button" className={role==='student'?'selected':''} onClick={()=>{setRole('student');setError('')}}><UserRound size={22}/> Студент</button><button type="button" className={role==='teacher'?'selected':''} onClick={()=>{setRole('teacher');setError('')}}><GraduationCap size={22}/> Оқытушы</button></div>{role==='student'&&<><label>Студент<select required value={name} onChange={e=>setName(e.target.value)}><option value="">Студентті таңдаңыз / Выберите студента</option>{STUDENT_NAMES.map(n=><option key={n} value={n}>{n}</option>)}</select></label><label>Топ / Группа<input value="БҚ-332" readOnly /></label><label>Жеке код / Персональный код<input required inputMode="numeric" pattern="[0-9]{4}" maxLength={4} type="password" autoComplete="off" placeholder="0000" value={code} onChange={e=>setCode(e.target.value)}/></label></>}{role==='teacher'&&<label>Оқытушының жеке коды<input required inputMode="numeric" pattern="[0-9]{4}" maxLength={4} type="password" autoComplete="off" placeholder="••••" value={code} onChange={e=>setCode(e.target.value)}/></label>}{error&&<p className="form-error" role="alert">{error}</p>}{role!=='none'&&<button className="primary wide" disabled={busy}>{busy?'Күтіңіз…':'Жүйеге кіру'}<ArrowRight size={17}/></button>}<small className="login-note">Оқу нұсқасы · Нақты хат алмасу үшін Supabase қосыңыз. 4 сандық кодтар қауіпсіз емес.</small></form></div></div>
}
function Exam({initial,onFinished,onLeave,notify}:{initial:Attempt;onFinished:(a:Attempt)=>void;onLeave:()=>void;notify:(e:unknown)=>void}){
 const[a,setA]=useState(initial),[answers,setAnswers]=useState(initial.answers),[index,setIndex]=useState(0),[now,setNow]=useState(Date.now()),[status,setStatus]=useState('Барлық жауап сақталған'),[submitting,setSubmitting]=useState(false),[confirm,setConfirm]=useState(false);
 const answersRef=useRef(answers),queue=useRef<Promise<unknown>>(Promise.resolve()),lastSaved=useRef(JSON.stringify(initial.answers)),offset=useRef(initial.server_time*1000-Date.now()),alive=useRef(true),finishing=useRef(false);
 useEffect(()=>{alive.current=true;const tick=setInterval(()=>setNow(Date.now()),500);return()=>{alive.current=false;clearInterval(tick)}},[]);
 const remaining=Math.max(0,Math.ceil((a.deadline*1000-now-offset.current)/1000));
 const persist=useCallback(()=>{const payload={...answersRef.current};if(JSON.stringify(payload)===lastSaved.current)return queue.current;setStatus('Сақталуда…');queue.current=queue.current.catch(()=>{}).then(async()=>{try{const next=await api<Attempt>(`/attempts/${initial.id}/answers`,'PUT',{answers:payload});lastSaved.current=JSON.stringify(payload);if(alive.current){setA(next);setStatus('Жауаптар сақталды');if(next.finished)onFinished(next)}}catch(e){if(alive.current){setStatus('Сақталмады · қайта әрекет жасалады');notify(e)}throw e}});return queue.current},[initial.id,notify,onFinished]);
 useEffect(()=>{const timeout=setTimeout(()=>{void persist().catch(()=>{})},450);return()=>clearTimeout(timeout)},[answers,persist]);
 useEffect(()=>{const retry=setInterval(()=>{if(!finishing.current)void persist().catch(()=>{})},5000);return()=>clearInterval(retry)},[persist]);
 async function finish(){if(finishing.current)return;finishing.current=true;setSubmitting(true);try{await queue.current.catch(()=>{});const next=await api<Attempt>(`/attempts/${a.id}/submit`,'POST',{answers:answersRef.current});onFinished(next)}catch(e){notify(e);finishing.current=false;setSubmitting(false);setStatus('Жіберілмеді. Қайталап көріңіз.')}}
 useEffect(()=>{if(remaining===0&&!finishing.current)void finish()},[remaining]);
 useEffect(()=>{const warn=(e:BeforeUnloadEvent)=>{e.preventDefault()};window.addEventListener('beforeunload',warn);return()=>window.removeEventListener('beforeunload',warn)},[]);
 const q=a.questions[index],count=Object.keys(answers).length;
 async function leave(){try{await persist();onLeave()}catch{/* keep exam visible */}}
 return <div className="exam-layout"><section className="panel exam-main"><div className="exam-top"><button className="text-button" onClick={leave} disabled={submitting}><ChevronLeft size={17}/>Сақтап шығу</button><span className="pill neutral">{a.subject}</span></div><h2>{a.title}</h2><div className="exam-progress"><div><span>Сұрақ {index+1} / {a.questions.length}</span><span>{count} жауап берілді</span></div><div className="progress-track"><span style={{width:count/a.questions.length*100+'%'}}/></div></div><div className="question-block"><span className="eyebrow">{q.points} ҰПАЙ · БІР ДҰРЫС ЖАУАП</span><h3>{q.text}</h3><div className="answers" role="radiogroup" aria-label="Жауаптар">{q.options.map((option,i)=><button role="radio" aria-checked={answers[String(q.id)]===i} disabled={submitting||remaining===0} className={answers[String(q.id)]===i?'answer chosen':'answer'} key={i} onClick={()=>{const next={...answersRef.current,[String(q.id)]:i};answersRef.current=next;setAnswers(next)}}><span className="answer-letter">{String.fromCharCode(65+i)}</span><span>{option}</span>{answers[String(q.id)]===i&&<Check size={18}/>}</button>)}</div></div><div className="question-nav"><button className="secondary" disabled={index===0} onClick={()=>setIndex(index-1)}><ChevronLeft size={16}/>Алдыңғы</button><span className="save-status"><Save size={14}/>{status}</span>{index<a.questions.length-1?<button className="primary" onClick={()=>setIndex(index+1)}>Келесі<ChevronRight size={16}/></button>:<button className="primary" onClick={()=>setConfirm(true)} disabled={submitting}>Аяқтау<Check size={16}/></button>}</div></section><aside className="exam-aside"><section className={'panel timer-panel '+(remaining<60?'urgent':'')}><Clock size={22}/><span>Қалған уақыт</span><strong>{String(Math.floor(remaining/60)).padStart(2,'0')}:{String(remaining%60).padStart(2,'0')}</strong><p>Уақыт аяқталса, сақталған жауаптар автоматты бағаланады.</p></section><section className="panel"><h3>Сұрақтар навигациясы</h3><div className="question-grid">{a.questions.map((question,i)=><button key={question.id} className={(answers[String(question.id)]!==undefined?'answered ':'')+(index===i?'current':'')} onClick={()=>setIndex(i)} aria-label={'Сұрақ '+(i+1)}>{i+1}</button>)}</div><div className="question-key"><span><i/>Жауап берілді</span><span><i/>Жауап жоқ</span></div><button className="primary wide" onClick={()=>setConfirm(true)} disabled={submitting}>{submitting?'Жіберілуде…':'Тестті аяқтау'}</button></section></aside>{confirm&&<div className="modal-overlay"><section className="modal small" role="dialog" aria-modal="true" aria-label="Тестті аяқтау"><h2>Тестті аяқтайсыз ба?</h2><p>{a.questions.length} сұрақтың {count} сұрағына жауап берілді. Жауап берілмеген сұрақтарға 0 ұпай беріледі.</p><div className="modal-actions"><button className="secondary" onClick={()=>setConfirm(false)} disabled={submitting}>Жалғастыру</button><button className="primary" onClick={()=>{setConfirm(false);void finish()}} disabled={submitting}>Жіберу<Check size={16}/></button></div></section></div>}</div>
}
function Review({attempt:a,onClose}:{attempt:Attempt;onClose:()=>void}){return <div className="modal-overlay" onClick={onClose}><GlassModal className="review" onDismiss={onClose} aria-label="Тест нәтижесі" onClick={e=>e.stopPropagation()}><div className="modal-head"><div><span className="eyebrow">ТЕСТ НӘТИЖЕСІ {a.demo?'· ДЕМО':''}</span><h2>{a.title}</h2></div><button className="icon-button" aria-label="Жабу" onClick={onClose}><X/></button></div><div className={'review-summary '+(a.passed?'success':'')}><div className="result-circle">{Math.round(a.score)}<small>%</small></div><div><h3>{a.passed?'Тест сәтті тапсырылды!':'Дайындықты жалғастырыңыз'}</h3><p>{a.earned} / {a.total} ұпай · Өту шегі {a.pass_score}%</p><p>{date(a.started)} · {Math.round(((a.finished??a.deadline)-a.started)/60)} минут</p></div></div><h3 className="review-label">Жауаптарды талдау</h3>{a.questions.map((q,i)=>{const chosen=a.answers[String(q.id)];const correct=chosen===q.correct;return <div className="review-question" key={q.id}><div className="review-q-title"><span className={correct?'correct-dot':'wrong-dot'}>{correct?<Check size={15}/>:<X size={15}/>}</span><h4>{i+1}. {q.text}</h4><small>{correct?q.points:0}/{q.points}</small></div>{q.options.map((o,j)=><div key={j} className={'review-option '+(q.correct===j?'right':chosen===j?'wrong':'')}><span>{String.fromCharCode(65+j)}.</span>{o}{chosen===j&&<small>Сіздің жауабыңыз</small>}{q.correct===j&&<Check size={16}/>}</div>)}{chosen===undefined&&<p className="form-error">Жауап берілмеген</p>}{q.explanation&&<p className="explanation">{q.explanation}</p>}</div>})}<button className="primary wide" onClick={onClose}>Түсінікті<Check size={16}/></button></GlassModal></div>}
function Teacher({subjects,tests,notify,refresh}:{subjects:Subject[];tests:Test[];notify:(e:unknown)=>void;refresh:()=>Promise<void>}){
 const[draft,setDraft]=useState<Draft|null>(null),[editId,setEditId]=useState<number|null>(null),[busy,setBusy]=useState(false),[deleting,setDeleting]=useState<Test|null>(null),[subjectForm,setSubjectForm]=useState(false),[subjectName,setSubjectName]=useState(''),[subjectDesc,setSubjectDesc]=useState(''),[tab,setTab]=useState<'tests'|'students'>('tests'),[students,setStudents]=useState<{id:number;name:string;email:string;attempts:number;average:number|null}[]>([]),[message,setMessage]=useState('');
 useEffect(()=>{if(tab==='students')api<typeof students>('/teacher/students').then(setStudents).catch(notify)},[tab,notify]);
 function newTest(){setEditId(null);setDraft({subject_id:subjects[0]?.id??0,title:'',description:'',duration:15,pass_score:60,published:false,questions:[blankQuestion()]})}
 async function edit(t:Test){setBusy(true);try{const d=await api<Draft>(`/teacher/tests/${t.id}`);setDraft({...d,published:!!d.published});setEditId(t.id)}catch(e){notify(e)}finally{setBusy(false)}}
 async function save(e:React.FormEvent){e.preventDefault();if(!draft)return;setBusy(true);try{await api(editId?`/teacher/tests/${editId}`:'/teacher/tests',editId?'PUT':'POST',draft);setDraft(null);setMessage('Тест сәтті сақталды');await refresh()}catch(e){notify(e)}finally{setBusy(false)}}
 async function remove(){if(!deleting)return;setBusy(true);try{await api(`/teacher/tests/${deleting.id}`,'DELETE');setDeleting(null);setMessage('Тест архивтелді. Нәтижелер сақталды.');await refresh()}catch(e){notify(e)}finally{setBusy(false)}}
 function updateQuestion(i:number,patch:Partial<Draft['questions'][number]>){if(draft)setDraft({...draft,questions:draft.questions.map((q,j)=>i===j?{...q,...patch}:q)})}
 async function addSubject(e:React.FormEvent){e.preventDefault();setBusy(true);try{await api('/subjects','POST',{name:subjectName,description:subjectDesc,icon:'◈'});setSubjectForm(false);setSubjectName('');setSubjectDesc('');await refresh();setMessage('Жаңа пән қосылды')}catch(e){notify(e)}finally{setBusy(false)}}
 return <><div className="toolbar"><div className="segmented"><button onClick={()=>setTab('tests')} className={tab==='tests'?'active':''}>Тесттер</button><button onClick={()=>setTab('students')} className={tab==='students'?'active':''}>Студенттер</button></div><div className="button-row"><button className="primary" onClick={newTest} disabled={!subjects.length}><Plus size={17}/>Жаңа тест</button></div></div>{message&&<div className="success-message" role="status"><CheckCircle2 size={18}/>{message}<button className="icon-button" onClick={()=>setMessage('')} aria-label="Жабу"><X size={15}/></button></div>}
 {tab==='tests'?<section className="panel"><div className="panel-head"><div><h3>Тесттерді басқару</h3><p>Жарияланбаған тесттер студенттерге көрінбейді</p></div><span className="pill neutral">{tests.length} тест</span></div>{tests.length?<div className="table-scroll"><table><thead><tr><th>ТЕСТ</th><th>СҰРАҚ</th><th>УАҚЫТ</th><th>МӘРТЕБЕСІ</th><th>ӘРЕКЕТТЕР</th></tr></thead><tbody>{tests.map(t=><tr key={t.id}><td><strong>{t.title}</strong><small>{t.subject}</small></td><td>{t.question_count}</td><td>{t.duration} мин</td><td><span className={t.published?'badge pass':'badge'}>{t.published?'Жарияланған':'Жоба'}</span></td><td><div className="button-row"><button className="icon-button" disabled={busy} onClick={()=>edit(t)} aria-label={'Өңдеу '+t.title}><Pencil size={17}/></button><button className="icon-button danger" disabled={busy} onClick={()=>setDeleting(t)} aria-label={'Архивтеу '+t.title}><Trash2 size={17}/></button></div></td></tr>)}</tbody></table></div>:<Empty text="Алғашқы тестті қосыңыз"/>}</section>:<section className="panel"><div className="panel-head"><div><h3>Студенттердің үлгерімі</h3><p>Барлық тіркелген студенттер</p></div></div><div className="table-scroll"><table><thead><tr><th>СТУДЕНТ</th><th>EMAIL</th><th>ӘРЕКЕТТЕР</th><th>ОРТАША НӘТИЖЕ</th></tr></thead><tbody>{students.map(s=><tr key={s.id}><td><strong>{s.name}</strong></td><td>{s.email}</td><td>{s.attempts}</td><td>{s.average!==null?s.average+'%':'—'}</td></tr>)}</tbody></table></div></section>}
 {draft&&<div className="modal-overlay"><form className="modal editor" role="dialog" aria-modal="true" aria-label="Тест редакторы" onSubmit={save}><div className="modal-head"><div><span className="eyebrow">ОҚЫТУШЫ ҚҰРАЛДАРЫ</span><h2>{editId?'Тестті өңдеу':'Жаңа тест құру'}</h2></div><button type="button" className="icon-button" onClick={()=>{if(window.confirm('Өзгерістерді сақтамай жабасыз ба?'))setDraft(null)}} aria-label="Жабу"><X/></button></div><div className="form-grid"><label className="span-two">Тест атауы<input value={draft.title} onChange={e=>setDraft({...draft,title:e.target.value})} required minLength={3} maxLength={150}/></label><label>Пән<select value={draft.subject_id} onChange={e=>setDraft({...draft,subject_id:Number(e.target.value)})}>{subjects.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select></label><label>Уақыт шектеуі, минут<input type="number" min={1} max={180} required value={draft.duration} onChange={e=>setDraft({...draft,duration:Number(e.target.value)})}/></label><label>Өту шегі, %<input type="number" min={1} max={100} required value={draft.pass_score} onChange={e=>setDraft({...draft,pass_score:Number(e.target.value)})}/></label><label>Мәртебесі<select value={draft.published?'yes':'no'} onChange={e=>setDraft({...draft,published:e.target.value==='yes'})}><option value="no">Жоба — студентке көрінбейді</option><option value="yes">Жарияланған — қолжетімді</option></select></label><label className="span-two">Сипаттама<textarea value={draft.description} maxLength={1000} onChange={e=>setDraft({...draft,description:e.target.value})}/></label></div><div className="editor-section-head"><h3>Сұрақтар <span className="muted">({draft.questions.length})</span></h3><span className="muted">Дұрыс жауапты шеңбермен белгілеңіз</span></div>{draft.questions.map((q,i)=><section className="question-editor" key={i}><div className="editor-q-head"><strong>Сұрақ {i+1}</strong><button type="button" className="icon-button danger" disabled={draft.questions.length<=1} onClick={()=>setDraft({...draft,questions:draft.questions.filter((_,j)=>i!==j)})} aria-label={'Сұрақты жою '+(i+1)}><Trash2 size={16}/></button></div><label>Сұрақ мәтіні<textarea required minLength={3} maxLength={2000} value={q.text} onChange={e=>updateQuestion(i,{text:e.target.value})}/></label><div className="option-editors">{q.options.map((o,j)=><label className="option-editor" key={j}><input aria-label={'Дұрыс жауап '+(j+1)} type="radio" name={'correct-'+i} checked={q.correct===j} onChange={()=>updateQuestion(i,{correct:j})}/><span>{String.fromCharCode(65+j)}</span><input aria-label={'Жауап '+(j+1)} required maxLength={1000} value={o} onChange={e=>updateQuestion(i,{options:q.options.map((v,k)=>j===k?e.target.value:v)})}/></label>)}</div><div className="form-grid"><label>Ұпай<input type="number" min={1} max={20} required value={q.points} onChange={e=>updateQuestion(i,{points:Number(e.target.value)})}/></label><label>Түсіндірме<input maxLength={2000} value={q.explanation} onChange={e=>updateQuestion(i,{explanation:e.target.value})}/></label></div></section>)}<button className="secondary wide" type="button" disabled={draft.questions.length>=100} onClick={()=>setDraft({...draft,questions:[...draft.questions,blankQuestion()]})}><Plus size={17}/>Сұрақ қосу</button><div className="editor-save"><p className="muted">Өңдеу басталған әрекеттер мен ескі нәтижелерді өзгертпейді.</p><button className="primary" disabled={busy}><Save size={17}/>{busy?'Сақталуда…':'Тестті сақтау'}</button></div></form></div>}
 {deleting&&<div className="modal-overlay"><section className="modal small" role="dialog" aria-modal="true" aria-label="Тестті архивтеу"><h2>Тестті архивтеу</h2><p>«{deleting.title}» жаңа әрекеттер үшін жабылады. Бұрынғы нәтижелер және басталған әрекеттер сақталады.</p><div className="modal-actions"><button className="secondary" onClick={()=>setDeleting(null)}>Бас тарту</button><button className="primary danger-bg" onClick={remove} disabled={busy}>Архивтеу</button></div></section></div>}
 {subjectForm&&<div className="modal-overlay"><form className="modal small" onSubmit={addSubject} role="dialog" aria-modal="true" aria-label="Пән қосу"><div className="modal-head"><h2>Пән қосу</h2><button className="icon-button" type="button" onClick={()=>setSubjectForm(false)} aria-label="Жабу"><X/></button></div><label>Пән атауы<input required minLength={2} maxLength={100} value={subjectName} onChange={e=>setSubjectName(e.target.value)}/></label><label>Сипаттама<textarea maxLength={500} value={subjectDesc} onChange={e=>setSubjectDesc(e.target.value)}/></label><button className="primary wide" disabled={busy}>Пәнді сақтау<Save size={16}/></button></form></div>}
 </>
}
function LearningOverview({user,subjects,onOpen}:{user:User;subjects:Subject[];onOpen:()=>void}){
 const [done,setDone]=useState<Record<string,boolean>>(()=>{try{return JSON.parse(localStorage.getItem('skas-learning-progress-'+user.role+'-'+user.id)||'{}')}catch{return {}}});
 useEffect(()=>{if(import.meta.env.VITE_SKAS_BACKEND==='1'&&user.role==='student')school<{lesson_id:string}[]>('progress').then(rows=>setDone(prev=>({...prev,...Object.fromEntries(rows.map(x=>[x.lesson_id,true]))}))).catch(()=>{})},[user.id,user.role]);
 const count=learningData.flatMap(c=>c.lessons).filter(l=>done[l.id]).length,percent=Math.round(count/140*100);
 return <GlassCard className="learning-overview"><div className="panel-head"><h3>Оқу прогресі</h3><button className="icon-button" aria-label="Сабақтарды ашу" onClick={onOpen}><MoreHorizontal size={19}/></button></div><div className="learning-overview-body"><button className="progress-ring" onClick={onOpen} aria-label={'Оқу прогресі '+percent+'%'} style={{'--progress':percent+'%'} as React.CSSProperties}><span><strong>{percent}%</strong><small>{count} / 140 сабақ</small></span></button><div className="course-legend">{learningData.filter(c=>subjects.some(s=>s.id===c.subject_id)).slice(0,4).map((c,i)=><div key={c.subject_id}><i style={{background:['#7fe5d4','#c8efff','#e6c8ff','#91c9ff'][i]}}/><span title={subjects.find(s=>s.id===c.subject_id)?.name}>{["Web-технологии","ООП","Программное ПО","Программирование","Базы данных","Графика","DevSecOps"][c.subject_id-1]}</span><strong>{Math.round(c.lessons.filter(l=>done[l.id]).length/c.lessons.length*100)}%</strong></div>)}</div></div></GlassCard>
}
createRoot(document.getElementById('root')!).render(<App/>);




